package com.honorablemobile

import android.app.AlertDialog
import android.net.Uri
import app.honorable.editor.EditorAccessMode
import org.junit.Assert.*
import org.junit.Test

/** Real visible-approval/project mutation gates, with metadata-only dialog membership. */
class VideoMomentNoteTextTest {
 private val unsafe=Class.forName("sun.misc.Unsafe").getDeclaredField("theUnsafe").apply{isAccessible=true}.get(null)as sun.misc.Unsafe
 private fun set(a:Any,n:String,v:Any?)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.set(a,v)
 private fun get(a:Any,n:String)=a.javaClass.getDeclaredField(n).apply{isAccessible=true}.get(a)
 private fun call(a:Any,n:String,vararg args:Any?)=a.javaClass.declaredMethods.single{it.name==n&&it.parameterCount==args.size}.apply{isAccessible=true}.invoke(a,*args)
 private fun activity()=(unsafe.allocateInstance(HonorableVideoEditorActivity::class.java)as HonorableVideoEditorActivity).also{val p=VideoEditProject(5000);p.restore(listOf(VideoSegment(0,5000,captions=listOf(VideoCaption(0,500,"A"),VideoCaption(1000,1500,"B")),captionSourceUri="content://synthetic/subtitles")),soundtrack=VideoSoundtrack("content://synthetic/music",10000,loop=false));set(it,"project",p);set(it,"source",Uri.parse("content://synthetic/video"));set(it,"primaryDurationMs",5000L);set(it,"accessMode",EditorAccessMode.GUEST_BASIC);set(it,"workspaceActive",true);set(it,"importedSources",linkedMapOf<String,VideoSource>())}
 private fun showing(d:AlertDialog,value:Boolean){android.app.Dialog::class.java.getDeclaredField("mDecor").apply{isAccessible=true}.set(d,if(value)unsafe.allocateInstance(android.view.View::class.java)else null)}
 private fun dialog()=(unsafe.allocateInstance(AlertDialog::class.java)as AlertDialog).also{showing(it,true)}
 private fun capture(a:HonorableVideoEditorActivity)=call(a,"captureCaptionReview")as VideoCaptionReviewState
 private fun parse(text:String,duration:Long=10000)=VideoMomentNoteText.parse(text,duration)
 @Test fun sourceSecondsBecomeSortedExactMillisecondBookmarks(){assertEquals(listOf(VideoMomentNote(1250,"Opening"),VideoMomentNote(8500,"Close-up")),parse("8.500 | Close-up\n1.250 | Opening"))}
 @Test fun crlfBlankRowsTrimmingAndLiteralPipesInLabelsArePreserved(){assertEquals(listOf(VideoMomentNote(0,"Zero | alt"),VideoMomentNote(1001,"Later")),parse(" \r\n 0 | Zero | alt \r\n\r\n1.001 | Later\r\n"))}
 @Test fun malformedRowsAndAmbiguousNumbersAreRefusedTogether(){for(text in listOf(""," ","1 label","1;label","1e0 | label","-1 | label","+1 | label","1:00 | label","NaN | label","1.0001 | label","1,5 | label","1 | ","1 | Good\ninvalid"))assertTrue(text,runCatching{parse(text)}.isFailure)}
 @Test fun existingUnicodeLabelLimitsAndControlRulesApply(){assertEquals("界".repeat(80),parse("1 | "+"界".repeat(80)).single().label);assertEquals("😀".repeat(40),parse("1 | "+"😀".repeat(40)).single().label);for(label in listOf("x".repeat(81),"bad\tlabel","bad\u0000label","\uD800"))assertTrue(runCatching{parse("1 | "+label)}.isFailure)}
 @Test fun duplicateNormalizedTimesAndSourceEndAreRefused(){for(text in listOf("1 | A\n1.000 | B","10 | End","10.001 | Outside"))assertTrue(runCatching{parse(text)}.isFailure);assertEquals(9999L,parse("9.999 | Last").single().sourceMs);assertTrue(runCatching{parse("0 | A",0)}.isFailure)}
 @Test fun rowsTextAndReturnedListAreBoundedAndImmutable(){assertEquals(100,parse((0 until 100).joinToString("\n"){"${it/1000.0} | $it"}).size);assertTrue(runCatching{parse((0..100).joinToString("\n"){"${it/1000.0} | $it"})}.isFailure);assertTrue(runCatching{parse(" ".repeat(16001))}.isFailure);val list=parse("1 | A");try{(list as MutableList).clear();fail("mutable") }catch(_:UnsupportedOperationException){}}
 @Test fun mergeRetainsExistingNotesAndInputSnapshots(){val first=VideoMomentNote(1000,"First");val catalog=VideoMomentNotes(10000,listOf(first));val incoming=mutableListOf(VideoMomentNote(5000,"New"));val merged=VideoMomentNoteText.merge(catalog,incoming);incoming.clear();assertEquals(listOf(first,VideoMomentNote(5000,"New")),merged.notes);assertEquals(listOf(first),catalog.notes)}
 @Test fun existingTimestampNeverGetsOverwrittenEvenWithSameLabel(){val first=VideoMomentNote(1000,"First");val catalog=VideoMomentNotes(10000,listOf(first));for(note in listOf(first,first.copy(label="Replacement"))){assertTrue(runCatching{VideoMomentNoteText.merge(catalog,listOf(note))}.isFailure);assertEquals(listOf(first),catalog.notes)};assertTrue(runCatching{VideoMomentNoteText.merge(catalog,emptyList())}.isFailure)}
 @Test fun combinedCapacityAndSourceBoundsFailWithoutPartialMerge(){val catalog=VideoMomentNotes(10000,(0 until 99).map{VideoMomentNote(it.toLong(),"Existing")});assertEquals(100,VideoMomentNoteText.merge(catalog,listOf(VideoMomentNote(5000,"One"))).notes.size);assertTrue(runCatching{VideoMomentNoteText.merge(catalog,listOf(VideoMomentNote(5000,"One"),VideoMomentNote(6000,"Two")))}.isFailure);assertEquals(99,catalog.notes.size);assertTrue(runCatching{VideoMomentNoteText.merge(catalog,listOf(VideoMomentNote(10000,"End")))}.isFailure)}
 @Test fun mergedCatalogSurvivesExistingPrivateCodecExactly(){val catalog=VideoMomentNoteText.merge(VideoMomentNotes(10000,listOf(VideoMomentNote(1,"Original"))),parse("1.234 | 界\n9.999 | Last"));assertEquals(catalog,VideoMomentCodec.decode(VideoMomentCodec.encode(catalog)));assertTrue(VideoMomentCodec.encode(catalog).size<=VideoMomentCodec.MAX_BYTES)}
 @Test fun productionStoreReadsLatestCatalogAndGuardsBeforeWriting(){val dir=java.nio.file.Files.createTempDirectory("synthetic-note-import-").toFile();try{val uri="content://synthetic/note-import";val file=java.io.File(dir,VideoMomentCodec.storageKey("guest-basic",uri)+".bin");val latest=VideoMomentNotes(10000,listOf(VideoMomentNote(1000,"Already saved")));val bytes=VideoMomentCodec.encode(latest);file.writeBytes(bytes);val store=VideoMomentNoteStore(dir,"guest-basic",uri,10000);var guards=0;try{store.addAll(parse("5 | New")){guards++;error("stale approval")};fail("wrote") }catch(e:IllegalStateException){assertEquals("stale approval",e.message)};assertEquals(1,guards);assertArrayEquals(bytes,file.readBytes());try{store.addAll(parse("1 | Duplicate")){guards++;fail("duplicate reached write guard")};fail("duplicate accepted") }catch(_:IllegalArgumentException){};assertEquals(1,guards);assertArrayEquals(bytes,file.readBytes());assertEquals(latest,store.load())}finally{dir.deleteRecursively()}}
 @Test fun originalStoreApiRemainsAlongsideBatchMerge(){val methods=VideoMomentNoteStore::class.java.declaredMethods;for(name in listOf("load","add","rename","remove","addAll"))assertTrue(name,methods.any{it.name==name});assertTrue(methods.any{it.name=="addAll"&&it.parameterCount==2})}
 private fun fixture():Triple<HonorableVideoEditorActivity,AlertDialog,VideoActionReview>{val a=activity();val d=dialog();val r=VideoActionReview();r.open(d);set(a,"momentReviewRequest",r);set(a,"momentReviewDialog",d);set(a,"captionReviewDialogs",linkedSetOf(d));return Triple(a,d,r)}
 private fun perform(a:HonorableVideoEditorActivity,d:AlertDialog,r:VideoActionReview,review:VideoCaptionReviewState,action:(()->Unit)->Unit)=call(a,"performMomentReview",d,r,review,action)as Boolean
 @Test fun approvedImportIsOneUseAndKeepsProjectHistoryAndMusic(){val(a,d,r)=fixture();val p=get(a,"project")as VideoEditProject;val clips=p.segments;val music=p.soundtrack;var stored=VideoMomentNotes(5000,listOf(VideoMomentNote(0,"Original")));val review=capture(a);assertTrue(perform(a,d,r,review){guard->guard();stored=VideoMomentNoteText.merge(stored,parse("1 | New",5000));guard()});assertEquals(2,stored.notes.size);assertSame(clips,p.segments);assertSame(music,p.soundtrack);assertFalse(p.canUndo);assertFalse(perform(a,d,r,review){fail("duplicate import")})}
 @Test fun staleSourceSessionOrGenerationCannotReachImportSideEffect(){for(flag in listOf("pause","source","duration","mode","generation","busy","recovery")){val(a,d,r)=fixture();val review=capture(a);when(flag){"pause"->set(a,"workspaceActive",false);"source"->set(a,"source",Uri.parse("content://synthetic/other"));"duration"->set(a,"primaryDurationMs",5001L);"mode"->set(a,"accessMode",EditorAccessMode.ACCOUNT);"generation"->set(a,"captionReviewGeneration",review.generation+1);"busy"->set(a,"saving",true);else->set(a,"recoveryBytes",byteArrayOf(1))};assertFalse(flag,perform(a,d,r,review){fail("import")});assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
 @Test fun backStageAndInvalidTextDoNotReviveOldApproval(){val(a,old,r)=fixture();val review=capture(a);assertTrue(runCatching{parse("bad")}.isFailure);assertTrue(r.owns(old));val next=dialog();r.open(next);r.dismiss(old);set(a,"momentReviewDialog",next);set(a,"captionReviewDialogs",linkedSetOf(next));assertFalse(perform(a,old,r,review){fail("old save")});assertTrue(r.owns(next));assertTrue(perform(a,next,r,review){it()})}
 @Test fun pausedBusyOrRecoveringImportEntryPrecedesStorageAndWidgets(){for(flag in listOf("pause","busy","recovery")){val a=activity();when(flag){"pause"->set(a,"workspaceActive",false);"busy"->set(a,"saving",true);else->set(a,"recoveryBytes",byteArrayOf(1))};call(a,"importMomentNotes");assertNull(get(a,"momentReviewRequest"));assertNull(get(a,"captionReviewDialogs"));assertFalse((get(a,"project")as VideoEditProject).canUndo)}}
}
